import java.util.*;class RiverSpacingTest{public static void main(String[]args){int n=128;float[] h=new float[n*n];int[] parent=new int[n*n];Arrays.fill(parent,-1);for(int z=0;z<n;z++)for(int x=0;x<n;x++){h[z*n+x]=z>=120?60:180-z;if(z<120)parent[z*n+x]=(z+1)*n+x;}var starts=new ArrayList<Integer>();for(int x:new int[]{16,24,32,64,72,104})starts.add(16*n+x);var flow=new EnvironmentNodes.Drainage(parent,h);var selected=RiverNetworkPlanner.select(starts,h,flow,n,62,6,null,()->false,12);if(selected.size()!=3)throw new AssertionError("Parallel coastal rivers not reduced: "+selected.size());for(int a:selected)for(int b:selected)if(a!=b&&Math.abs(a%n-b%n)<30)throw new AssertionError("Coastal outlets crowded");System.out.println("PASS: six parallel coastal candidates reduced to three well-spaced river systems");}}
